    def cargarComboBox(self):
        cursor=self.con.cursor()
        sql="select tipo from tipo"
        cursor.execute(sql)
        resultado=cursor.fetchall()
        for registro in resultado:
                texto = "" if registro[0] is None else str(registro[0])
                self.comboBox.addItem(texto)
        cursor.close()
        
        
    def variarDatos(self, caso):
        if caso == "a":
            self.contador = 0
        if caso == "b":
            if self.contador != 0:
                self.contador -=1
        if caso == "c":
            if self.contador != self.maximo:
                self.contador +=1
        if caso == "d":
            self.contador = self.maximo
            
        
    def cargarDatos(self):
        cursor=self.con.cursor()
        sql="select * from piezas"
        cursor.execute(sql)
        resultado=cursor.fetchall()
        self.maximo = len(resultado)-1
        self.lineEdit.setText("" if resultado[self.contador][0] is None else str(resultado[self.contador][0]))
        self.lineEdit_2.setText("" if resultado[self.contador][1] is None else str(resultado[self.contador][1]))
        self.lineEdit_3.setText("" if resultado[self.contador][2] is None else str(resultado[self.contador][2]))
        self.lineEdit_4.setText("" if resultado[self.contador][3] is None else str(resultado[self.contador][3]))
        self.comboBox.setCurrentIndex(resultado[self.contador][4]-1)
        cursor.close()

